import { bom, type OperationFn } from "@protoboardai/core";

/** BOM export: quantities multiplied through the instance tree, one line per definition, with origin. */
export const bom_: OperationFn = (ctx) => {
  const rows = bom(ctx.project);
  const out = ctx.inputs.out ?? "docs";
  const md = [
    `# Bill of materials — ${ctx.project.name}`,
    "",
    "Generated by `protoboard run bom` from the resolved project. Do not edit by hand.",
    "",
    "| Qty | Part | Manufacturer | Part number | Origin |",
    "| ---: | --- | --- | --- | --- |",
    ...rows.map((r) => `| ${r.quantity} | ${r.name ?? r.definition} (\`${r.definition}\`) | ${r.manufacturer ?? ""} | ${r.partNumber ?? ""} | ${r.origin} |`),
    "",
  ].join("\n");
  ctx.writeOutput(`${out}/bom.md`, md, "BOM (markdown)");
  ctx.writeOutput(`${out}/bom.json`, JSON.stringify(rows, null, 2) + "\n", "BOM (JSON)");
  const total = rows.reduce((s, r) => s + r.quantity, 0);
  return { status: "succeeded", summary: `${rows.length} lines, ${total} items`, data: { lines: rows.length, items: total } };
};
export { bom_ as bom };
